#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-06

# check-version-consistency.sh
#
# CI gate: verifies the plugin version declared in the marketplace manifest
# matches the version declared in the (built) plugin manifest.
#
# Background (A0 pre-flight audit): release.yml's "Bump patch version" step
# updates package.json, manifests/academic-writer.json (the pre-build source
# manifest), and .claude-plugin/marketplace.json — but it does NOT update the
# already-built plugins/academic-writer/.claude-plugin/plugin.json, and does
# NOT re-run `npm run build`. That built plugin.json is itself committed to
# git (verified via `git ls-files`), so a version bump commit can silently
# leave the built plugin.json one version behind. This script exists to catch
# that class of desync.
#
# Locations (verified against the actual repo, do not assume):
#   Marketplace manifest : .claude-plugin/marketplace.json
#     - top-level .version            (marketplace/catalog version)
#     - .plugins[0].version           (the academic-writer plugin's version, as
#                                       declared in the marketplace listing)
#   Plugin manifest (built) : plugins/academic-writer/.claude-plugin/plugin.json
#     - .version
#
# Note: there is also a pre-build source manifest at manifests/academic-writer.json
# and a root package.json, both of which independently carry a "version" field
# and are kept in lockstep by release.yml's bump step. Those are NOT compared by
# this script (its job is specifically the marketplace <-> built-plugin.json pair,
# which is the pair release.yml currently does NOT gate). See
# check-built-manifest.sh for source-vs-built manifest comparisons.
#
# Exit 0  -> versions match
# Exit 1  -> versions differ (or a required file/field is missing)

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"

MARKETPLACE_JSON="$PROJECT_ROOT/.claude-plugin/marketplace.json"
PLUGIN_JSON="$PROJECT_ROOT/plugins/academic-writer/.claude-plugin/plugin.json"
PLUGIN_NAME="academic-writer"

RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
NC='\033[0m'

fail() {
  echo -e "${RED}✗ check-version-consistency: $1${NC}" >&2
  exit 1
}

[[ -f "$MARKETPLACE_JSON" ]] || fail "marketplace manifest not found at $MARKETPLACE_JSON"
[[ -f "$PLUGIN_JSON" ]] || fail "plugin manifest not found at $PLUGIN_JSON (has the build been run? see scripts/build-plugins.sh)"

if command -v jq &>/dev/null; then
  MARKETPLACE_PLUGIN_VERSION=$(jq -r --arg name "$PLUGIN_NAME" \
    '.plugins[] | select(.name == $name) | .version' "$MARKETPLACE_JSON")
  PLUGIN_VERSION=$(jq -r '.version' "$PLUGIN_JSON")
else
  echo -e "${YELLOW}⚠ jq not found, falling back to grep/sed (less robust)${NC}" >&2
  # Best-effort fallback: grabs the first "version": "..." after the matching
  # plugin's "name": "academic-writer" entry in the plugins array.
  MARKETPLACE_PLUGIN_VERSION=$(awk -v name="\"$PLUGIN_NAME\"" '
    $0 ~ "\"name\": *" name { found=1 }
    found && /"version"/ { gsub(/[",]/, "", $0); sub(/.*: */, "", $0); print; exit }
  ' "$MARKETPLACE_JSON")
  PLUGIN_VERSION=$(grep -m1 '"version"' "$PLUGIN_JSON" | sed -E 's/.*"version": *"([^"]+)".*/\1/')
fi

[[ -n "$MARKETPLACE_PLUGIN_VERSION" && "$MARKETPLACE_PLUGIN_VERSION" != "null" ]] \
  || fail "could not read plugins[].version for \"$PLUGIN_NAME\" from $MARKETPLACE_JSON"
[[ -n "$PLUGIN_VERSION" && "$PLUGIN_VERSION" != "null" ]] \
  || fail "could not read .version from $PLUGIN_JSON"

echo "marketplace.json  plugins[\"$PLUGIN_NAME\"].version = $MARKETPLACE_PLUGIN_VERSION"
echo "plugin.json (built) .version                        = $PLUGIN_VERSION"

if [[ "$MARKETPLACE_PLUGIN_VERSION" != "$PLUGIN_VERSION" ]]; then
  fail "version mismatch: marketplace.json declares \"$MARKETPLACE_PLUGIN_VERSION\" but built plugin.json declares \"$PLUGIN_VERSION\". Run \`npm run build\` and/or fix release.yml's bump step to also update $PLUGIN_JSON."
fi

echo -e "${GREEN}✓ check-version-consistency: versions match ($PLUGIN_VERSION)${NC}"
exit 0
